import { useState, type FormEvent } from "react";

export function InviteForm() {
  const [email, setEmail] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    const result = await sendInvite(email); // a throw skips the next lines
    setError(result.error ?? null);
    setIsLoading(false);
  }

  return (
    <form onSubmit={handleSubmit}>
      <input value={email} onChange={(e) => setEmail(e.target.value)} />
      <button disabled={isLoading}>{isLoading ? "Sending…" : "Invite"}</button>
      {error && <p role="alert">{error}</p>}
    </form>
  );
}

import { useActionState } from "react";

type State = { error: string | null; email: string };

async function invite(_prev: State, formData: FormData): Promise<State> {
  const email = String(formData.get("email"));
  const { error } = await sendInvite(email);
  return error ? { error, email } : { error: null, email: "" };
}

export function InviteForm() {
  const [state, formAction, isPending] = useActionState(invite, {
    error: null,
    email: "",
  });

  return (
    <form action={formAction}>
      <input name="email" defaultValue={state.email} />
      <button disabled={isPending}>{isPending ? "Sending…" : "Invite"}</button>
      {state.error && <p role="alert">{state.error}</p>}
    </form>
  );
}

